<script lang="ts">
	import{onMount}from'svelte';import{api}from'$lib/api';import { formatMoney } from '$lib/money';import CursorPager from '$lib/components/CursorPager.svelte';type Item={id:string;allocation_id:string;booking_id:string;seller:string;route:string;state:string;provider_reference:string|null;amount_minor:number;currency:string;starts_at:string;settled_at:string|null};let items=$state<Item[]>([]);let message=$state('');let loading=$state(true);let nextCursor=$state('');let importing=$state(false);let importResult=$state('');let unmatchedRows=$state<{id:string;transaction_reference:string;settlement_reference:string|null;amount_minor:number;currency:string;settled_at:string;state:string}[]>([]);let reviewCursor=$state('');let reviewLoading=$state(false);	async function load(cursor=''){loading=true;try{const q=cursor?`?cursor=${encodeURIComponent(cursor)}`:'';const page=await api<{settlements:Item[];next_cursor:string}>(`/api/v1/ops/settlements${q}`);items=cursor?[...items,...page.settlements]:page.settlements;nextCursor=page.next_cursor;if(!cursor){const review=await api<{rows:typeof unmatchedRows;next_cursor:string}>('/api/v1/ops/settlements/import-rows');unmatchedRows=review.rows;reviewCursor=review.next_cursor}}catch(e){message=e instanceof Error?e.message:'Settlement records could not be loaded.'}finally{loading=false}}
	async function loadReview(cursor:string){reviewLoading=true;try{const review=await api<{rows:typeof unmatchedRows;next_cursor:string}>(`/api/v1/ops/settlements/import-rows?cursor=${encodeURIComponent(cursor)}`);unmatchedRows=[...unmatchedRows,...review.rows];reviewCursor=review.next_cursor}catch(e){message=e instanceof Error?e.message:'Review rows could not be loaded.'}finally{reviewLoading=false}}
	onMount(()=>load());
</script>
<svelte:head><title>Settlements — Ops · WantMyTime</title></svelte:head><section class="form-page app-page"><a class="back-link" href="/ops">← Operations</a><p class="eyebrow">Settlements</p><h1 class="page-heading">Provider settlement records.</h1><section class="readiness-panel"><h2>Import a provider settlement file</h2><p>Upload a normalized CSV with transaction_reference, settlement_reference, amount_minor, currency, and settled_at (RFC 3339). Exact matches are retained for reconciliation review. A manually uploaded file cannot prove provider settlement or mark a payout settled.</p><label>CSV file<input class="field" type="file" accept=".csv,text/csv" onchange={async(event)=>{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;importing=true;importResult='';try{const result=await api<{matched:number;unmatched:number;amount_mismatch:number;currency_mismatch:number;duplicates:number}>('/api/v1/ops/settlements/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:await file.text()});importResult=`Imported for review: ${result.matched} matched, ${result.unmatched} unmatched, ${result.amount_mismatch} amount mismatch, ${result.currency_mismatch} currency mismatch, ${result.duplicates} duplicate.`;await load()}catch(e){importResult=e instanceof Error?e.message:'Import failed.'}finally{importing=false}}}/></label>{#if importing}<p>Importing settlement rows…</p>{/if}{#if importResult}<p class="notice notice-info" aria-live="polite">{importResult}</p>{/if}</section>{#if message}<div class="notice notice-warning">{message}</div>{/if}{#if unmatchedRows.length}<section class="readiness-panel"><h2>Rows awaiting reconciliation</h2><div class="list-stack">{#each unmatchedRows as row}<article class="list-card"><div><strong>{row.state.replaceAll('_',' ')} · {row.currency==='NGN'?formatMoney(row.amount_minor,row.currency):`${row.currency} ${row.amount_minor} minor units`}</strong><p>{row.transaction_reference}{row.settlement_reference?` · settlement ${row.settlement_reference}`:''}</p><small>{new Date(row.settled_at).toLocaleString()}</small></div></article>{/each}</div><CursorPager cursor={reviewCursor} busy={reviewLoading} onNext={()=>loadReview(reviewCursor)}/></section>{/if}{#if loading&&!items.length}<p class="page-intro">Loading…</p>{:else if items.length}<div class="list-stack">{#each items as item}<article class="list-card"><div><strong>{item.seller} · {formatMoney(item.amount_minor,item.currency)}</strong><p>Booking {item.booking_id} · {item.route.replaceAll('_',' ')}</p><small>{item.state.replaceAll('_',' ')} · {item.provider_reference||'No provider reference'}</small><small>{item.settled_at?`Confirmed ${new Date(item.settled_at).toLocaleString()}`:'No matched provider settlement confirmation'}</small></div></article>{/each}</div><CursorPager cursor={nextCursor} busy={loading} onNext={()=>load(nextCursor)}/>{:else if !loading}<p class="page-intro">No settlement allocations exist yet. A verified allocation will appear here; collection remains disabled.</p>{/if}</section>
